mapper.select:
SELECT * FROM
(
SELECT A.*, ROWNUM RN
FROM (
select a.id,tqbz,nsrdzdah,tqsj,b.sbbw from tl_admin.yj_sbxx_hz  a,tl_bjts.sb_sbxx_sbsj b
where a.sbzt_dm= #{sbztDm} and (tqbz is null or sysdate-tqsj > #{delay}) and a.id=b.id(+)
and 10>a.tqcs
and  not exists (select 1 from tl_admin.yj_sbxx_hz C
where a.nsrdzdah=C.nsrdzdah and (C.tqbz is not null and #{delay} > sysdate-tqsj ))

    and length(b.sbbw) >= #{size}


    and  #{size} > length(b.sbbw)

) A where 1=1

    and ROWNUM <= #{end}

)
WHERE 1=1

    and RN >= #{start}


    ORDER BY #{orderByCaluse}

mapper.update:
UPDATE tl_admin.yj_sbxx_hz a SET a.tqbz = #{tqbz,jdbcType=VARCHAR}, a.tqsj = sysdate, a.tqcs = tqcs+1 WHERE id=#{id} and sbzt_dm ='20' and not exists (select 1 from tl_admin.yj_sbxx_hz C where a.nsrdzdah=C.nsrdzdah and a.id<>C.id and C.tqbz is not null and 10>C.tqcs and C.sbzt_dm ='20')
and a.tqbz = #{lastTqbz}
and a.tqbz is null


UPDATE tl_admin.yj_sbxx_hz a
			   	SET a.tqbz = null
			 	WHERE id=#{id}
